# Generated by manage.py generate_test_cases.
import json
from typing import Any

from bs4 import BeautifulSoup

from bloomerp.widgets.booking_availability_widget import BookingAvailabilityWidget
from bloomerp.tests.base import (
    BloomerpWidgetTestCase,
    WidgetScenario,
    WidgetOperation,
)


class TestBookingAvailabilityWidget(BloomerpWidgetTestCase):
    widget_class = BookingAvailabilityWidget

    def get_test_scenarios(self) -> list[WidgetScenario[BookingAvailabilityWidget]]:
        """Exercise rendered controls and Django form submission for the widget."""
        return [WidgetScenario(
            name="One serialized value for optional dates and repeatable hours",
            operations=[
                WidgetOperation(name="Render saved schedule", execute=self.render_schedule, result_validators=self.has_controls),
                WidgetOperation(name="Extract submitted schedule", execute=self.extract_schedule, result_validators=self.has_schedule),
            ],
        )]

    def render_schedule(self, widget: BookingAvailabilityWidget) -> str:
        """Render a stored schedule as a read-only detail field."""
        return widget.render("availability_hours", {"start_date": "2026-11-30"}, {"disabled": True})

    def has_controls(self, value: Any) -> bool:
        """Check the hidden value and the editor markup needed for browser interaction."""
        soup = BeautifulSoup(value, "html.parser")
        fieldset = soup.select_one('fieldset[disabled][bloomerp-component="booking-availability"]')
        if fieldset is None:
            return False
        payload = fieldset.select_one('input[type="hidden"][name="availability_hours"]')
        return (
            payload is not None
            and self.has_schedule(payload["value"])
            and len(fieldset.select('[data-availability-day]')) == 7
            and fieldset.select_one('template[data-availability-exception-template]') is not None
        )

    def extract_schedule(self, widget: BookingAvailabilityWidget) -> Any:
        """Read the output input without parsing it in the widget layer."""
        return widget.value_from_datadict({"availability_hours": '{"start_date":"2026-11-30"}'}, {}, "availability_hours")

    def has_schedule(self, value: Any) -> bool:
        """Confirm the same date survives widget rendering and submission."""
        return json.loads(value) == {"start_date": "2026-11-30"}
